    tut_title: "📚 Tutorial: using Moka with your key (and how much it costs)",
    tut_intro: "In 5 minutes you'll be reading with AI — spending cents. Here's the complete path, step by step.",
    tut_api_t: "🔑 What is this 'API' thing?",
    tut_api_d: "An API is the bridge connecting Moka to the AI YOU choose. The API key is like a password: you create it for free on the provider's site (DeepSeek, OpenAI…), paste it here and done — Moka now thinks with your AI. The provider charges you (cents per use); Moka is free.",
    tut_s1_t: "Step 1 — Choose your AI",
    tut_s1_d: "In the 🏆 price ranking you compare them all. To start, the cheapest that works great is DeepSeek V4 Flash (or GLM-4 Flash, the cheapest of all). Top quality? Claude Opus or GPT-5 — they cost more.",
    tut_s2_t: "Step 2 — Get your key (1 minute)",
    tut_s2_d: "On the provider's site: create the account, generate the key (API key) and add a small credit — US$ 5 lasts weeks with normal use. Direct links:",
    tut_s3_t: "Step 3 — Paste it in ⚙️ Settings",
    tut_s3_d: "Paste the key into Moka. It stays ENCRYPTED on your device — it never passes through our servers. You can delete it anytime.",
    tut_s4_t: "How much will it cost? (the math)",
    tut_s4_d1: "AI charges per TOKEN (small pieces of text — 1 token ≈ ¾ of a word). In the ranking you see each AI's price per 1 million tokens.",
    tut_s4_d2: "Examples with DeepSeek V4 Flash: translating 1 PAGE ≈ less than 1 cent · summarizing 1 book ≈ US$ 0.003 · translating the whole book ≈ US$ 0.03 · summarizing 1h of video ≈ US$ 0.002.",
    tut_s4_d3: "With a premium model (Claude Opus), multiply by ~40: still cents per book. You choose the price×quality balance — and can switch anytime.",
    tut_s5_t: "Track your spend",
    tut_s5_d: "The real spend shows in YOUR provider's dashboard (you see tokens used and remaining credit). Golden tip: set a SPENDING LIMIT in the provider's dashboard — never a surprise.",
    tut_video: "⚠️ And video? It's another system: with captions it's free; without captions, the key must be for audio transcription (Whisper/OpenAI) — price per hour: US$ 0.04–0.36.",
    tut_cta: "Done! Start with your shelf →",
