    byok_cost: "Moka is 100% free — no subscription, no purchases, no paywall. If you want the AI features, the (optional) cost is paid directly to your key's provider, outside the app: summary ≈ US$ 0.01–0.05 · full book translated ≈ US$ 0.50–2 · 1h of video ≈ US$ 2. Moka never charges anything.",
    byok_video_note: "⚠️ For BOOKS and TEXT, any key from the ranking above works. For VIDEOS without captions, see the 🎬 Video & Transcription section below — it uses an audio-transcription key (OpenAI/Whisper or Groq).",
