    free_title: "Moka est gratuit ☕",
    free_desc: "Tout est débloqué : vous l'utilisez avec VOTRE propre clé IA. Elle reste uniquement sur votre appareil, chiffrée — elle ne passe jamais par nos serveurs.",
    capa_login_benefit: "🔐 Connectez-vous avec Google (gratuit) : votre bibliothèque — livres, notes, traductions et progression — est gardée dans le cloud et s'ouvre sur tout appareil.",
    byok_get_key: "Comment obtenir votre clé IA (1 minute)",
    tut_title: "📚 Tutoriel : utiliser Moka avec votre clé (et combien ça coûte)",
    tut_intro: "Dans 5 minutes vous lisez avec l'IA — pour quelques centimes. Voici le chemin complet, pas à pas.",
    tut_api_t: "🔑 C'est quoi, cette « API » ?",
    tut_api_d: "L'API est le pont qui relie Moka à l'intelligence artificielle que VOUS choisissez. La clé API est comme un mot de passe : vous la créez gratuitement sur le site du fournisseur (DeepSeek, OpenAI…), vous la collez ici et voilà — Moka pense avec votre IA. C'est le fournisseur qui facture (quelques centimes); Moka est gratuit.",
    tut_s1_t: "Étape 1 — Choisissez votre IA",
    tut_s1_d: "Dans le 🏆 Classement des prix, vous comparez tout. Pour débuter, la moins chère qui marche très bien est DeepSeek V4 Flash (ou GLM-4 Flash, la moins chère de toutes). Qualité max ? Claude Opus ou GPT-5 — plus chers.",
    tut_s2_t: "Étape 2 — Obtenez votre clé (1 minute)",
    tut_s2_d: "Sur le site du fournisseur : créez le compte, générez la clé (API key) et ajoutez un petit crédit — 5 $US durent des semaines en usage normal. Liens directs :",
    tut_s3_t: "Étape 3 — Collez-la dans ⚙️ Réglages",
    tut_s3_d: "Collez la clé dans Moka. Elle reste CHIFFRÉE sur votre appareil — elle ne passe jamais par nos serveurs. Vous pouvez l'effacer quand vous voulez.",
    tut_s4_t: "Combien ça va coûter ? (le calcul)",
    tut_s4_d1: "L'IA facture au TOKEN (petits morceaux de texte — 1 token ≈ ¾ de mot). Dans le classement vous voyez le prix de chaque IA par million de tokens.",
    tut_s4_d2: "Exemples avec DeepSeek V4 Flash : traduire 1 PAGE ≈ moins de 1 centime · résumer 1 livre ≈ 0,003 $US · traduire le livre entier ≈ 0,03 $US · résumer 1 h de vidéo ≈ 0,002 $US.",
    tut_s4_d3: "Avec un modèle premium (Claude Opus), multipliez par ~40 : toujours des centimes par livre. Vous choisissez l'équilibre prix×qualité — et pouvez changer quand vous voulez.",
    tut_s5_t: "Suivez votre dépense",
    tut_s5_d: "La dépense réelle apparaît dans le tableau de bord de VOTRE fournisseur (tokens utilisés et crédit restant). Astuce en or : activez la LIMITE de dépense dans le tableau de bord — jamais de surprise.",
    tut_video: "⚠️ Et la vidéo ? C'est un autre système : avec sous-titres c'est gratuit ; sans sous-titres, la clé doit être pour la transcription audio (Whisper/OpenAI) — prix par heure : 0,04–0,36 $US.",
    tut_cta: "Prêt ! Commencez par votre étagère →",
