    free_desc: "Alles ist freigeschaltet: Sie nutzen es mit IHREM eigenen KI-Schlüssel. Er bleibt nur auf Ihrem Gerät, verschlüsselt — nie über unsere Server.",
    capa_login_benefit: "🔐 Mit Google anmelden (kostenlos): Ihre Bibliothek — Bücher, Notizen, Übersetzungen und Fortschritt — wird in der Cloud gespeichert und öffnet auf jedem Gerät.",
    byok_get_key: "So holen Sie Ihren KI-Schlüssel (1 Minute)",
    tut_title: "📚 Tutorial: Moka mit Ihrem Schlüssel nutzen (und was es kostet)",
    tut_intro: "In 5 Minuten lesen Sie mit KI — für Centbeträge. Hier der komplette Weg, Schritt für Schritt.",
    tut_api_t: "🔑 Was ist das, eine „API“?",
    tut_api_d: "Eine API ist die Brücke zwischen Moka und der künstlichen Intelligenz, die SIE wählen. Der API-Schlüssel ist wie ein Passwort: Sie erstellen ihn kostenlos auf der Seite des Anbieters (DeepSeek, OpenAI…), fügen ihn hier ein — fertig, Moka denkt mit Ihrer KI. Der Anbieter rechnet ab (Centbeträge); Moka ist kostenlos.",
    tut_s1_t: "Schritt 1 — Wählen Sie Ihre KI",
    tut_s1_d: "Im 🏆 Preisranking vergleichen Sie alle. Zum Start: die günstigste, die super funktioniert, ist DeepSeek V4 Flash (oder GLM-4 Flash, die günstigste von allen). Top-Qualität? Claude Opus oder GPT-5 — kosten mehr.",
    tut_s2_t: "Schritt 2 — Holen Sie Ihren Schlüssel (1 Minute)",
    tut_s2_d: "Auf der Anbieter-Seite: Konto erstellen, Schlüssel generieren (API key) und kleines Guthaben laden — 5 US$ reichen bei normalem Gebrauch wochenlang. Direktlinks:",
    tut_s3_t: "Schritt 3 — In ⚙️ Einstellungen einfügen",
    tut_s3_d: "Schlüssel in Moka einfügen. Er bleibt VERSCHLÜSSELT auf Ihrem Gerät — nie über unsere Server. Sie können ihn jederzeit löschen.",
    tut_s4_t: "Was kostet das? (die Rechnung)",
    tut_s4_d1: "Die KI rechnet pro TOKEN ab (Textstückchen — 1 Token ≈ ¾ Wort). Im Ranking sehen Sie den Preis jeder KI pro 1 Million Tokens.",
    tut_s4_d2: "Beispiele mit DeepSeek V4 Flash: 1 SEITE übersetzen ≈ unter 1 Cent · 1 Buch zusammenfassen ≈ 0,003 US$ · das ganze Buch übersetzen ≈ 0,03 US$ · 1 Std. Video zusammenfassen ≈ 0,002 US$.",
    tut_s4_d3: "Mit einem Premium-Modell (Claude Opus) mal ~40 rechnen: immer noch Cents pro Buch. Sie wählen die Balance Preis×Qualität — und können jederzeit wechseln.",
    tut_s5_t: "Kosten im Blick behalten",
    tut_s5_d: "Die echten Kosten sehen Sie im Dashboard IHRES Anbieters (verbrauchte Tokens und Restguthaben). Goldener Tipp: Aktivieren Sie dort das AUSGABENLIMIT — nie eine Überraschung.",
    tut_video: "⚠️ Und Video? Anderes System: mit Untertiteln gratis; ohne Untertitel braucht der Schlüssel eine Audio-Transkription (Whisper/OpenAI) — Preis pro Stunde: 0,04–0,36 US$.",
    tut_cta: "Fertig! Starten Sie mit Ihrem Regal →",
    rank_title: "🏆 KI-Preisranking",
