    rank_video_note: "⚠️ Video ist ein ANDERES System: nicht jede LLM reicht — Videos OHNE Untertitel zu transkribieren braucht eine Audio-API (Whisper). Preis pro Videostunde:",
    rank_per_hour: "pro Stunde",
    rank_cta: "Heute die günstigste nützliche: GLM-4 Flash + DeepSeek V4 Flash ☕",
    byok_cost: "Moka ist 100% kostenlos — kein Abo, keine Käufe, kein Paywall. Wenn du die KI-Funktionen willst, zahlst du die (optionale) Kosten direkt beim Anbieter deines Schlüssels, außerhalb der App: Zusammenfassung ≈ 0,01–0,05 $ · ganzes Buch übersetzt ≈ 0,50–2 $ · 1h Video ≈ 2 $. Moka berechnet nie etwas.",
    byok_video_note: "⚠️ Für BÜCHER und TEXTE reicht jeder Schlüssel aus dem Ranking oben. Für VIDEOS ohne Untertitel siehe den Abschnitt 🎬 Video & Transkription unten — dort wird ein Audio-Transkriptionsschlüssel verwendet (OpenAI/Whisper oder Groq).",
    vid_section_title: "Video & Transkription",
