    vid_cfg_diff: "Die Text-KI (Übersetzen/Zusammenfassen) nutzt den Schlüssel aus dem Ranking oben. Aber Video OHNE Untertitel ist ein anderes System: Moka HÖRT das Audio und transkribiert es mit einer Transkriptions-API (Whisper/OpenAI). Nicht jeder Text-Schlüssel reicht.",
